    },
    "factor_updates": [
      {
        "factor": "CDU polling lead in late February 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Polls place CDU ahead or near parity with Greens, with seat projections tilting toward CDU; increases likelihood of CDU winning the most seats."
      },
      {
        "factor": "Greens closing the gap",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens rising toward CDU levels reduces CDU's edge and introduces risk of a head-to-head by final tallies."
      },
      {
        "factor": "AfD as a spoiler",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "AfD's share can siphon votes from major parties, potentially narrowing CDU's seat lead."
      },
      {
        "factor": "Seat projections favor CDU",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "FGW/Infratest dimap projections consistently place CDU with the largest or near-largest seat share in late-February forecasts."
      },
      {
        "factor": "Electoral-system magnifying leads into seats",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "BW's mixed system tends to translate vote leads into seats, reinforcing CDU's comparative advantage."
      }
    ],
    "synthesis_rationale": "Starting from a 0.65 base anchor for the reference class, the combination of a persistent polling lead, corroborating seat projections, and rules-of-the-game from the electoral system justify a high posterior probability. Correlated factors (polls and seats) are weighted with modest-to-strong influence; uncertainty arises mainly from Greens momentum and turnout dynamics, which are acknowledged in the calibrated range rather than overturning the central conclusion."
  }
}

